VALUES (242826, 'tt0074858', NULL, 'Manthan', 'मंथन', 'movie', 1976, 'https://image.tmdb.org/t/p/w500/kvSfzxjWlTXPPnG0xUKQvP8Xgb.jpg', 'https://image.tmdb.org/t/p/original/yil0bvLs4pX4rw2buPzzwztz4jo.jpg', 'A veterinarian, Dr. Rao, makes a visit to a village, where he intends to commence a co-operative society dairy for the betterment of the rural people. The film is set against the backdrop of the White Revolution of India (Operation Flood) which started in 1970. It was entirely crowdfunded by 500,000 farmers who donated Rs. 2 each.', NULL, NULL, 1.3946, 6.588, 0, 10.02, '2026-10-17 04:47:13', '2026-10-17 04:47:13')
