VALUES (NULL, NULL, 228535, 'Remnant II', 'Remnant II', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6lnp.jpg', NULL, 'Remnant II is the sequel to the best-selling game Remnant: From the Ashes that pits survivors of humanity against new deadly creatures and god-like bosses across terrifying worlds. Play solo or co-op with two other friends to explore the depths of the unknown to stop an evil from destroying reality itself. To succeed, players will need to rely on their own skills and those of their team to overcome the toughest challenges and to stave off humanity’s extinction.', 'https://www.igdb.com/games/remnant-ii', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, NULL, 0, 1.02, '2026-10-17 04:47:13', '2026-10-17 04:47:13')
