VALUES (NULL, NULL, 364048, 'A Ragdoll Rage Game', 'A Ragdoll Rage Game', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob8a8.jpg', NULL, 'A Ragdoll Rage Game is a physics-based rage platformer where you grab, aim, and fling a ragdoll through challenging obstacles. The game also features secret badges, unlockable cosmetics, a built-in level editor, global leaderboards, and more.', 'https://www.igdb.com/games/a-ragdoll-rage-game', '["Linux", "PC (Microsoft Windows)", "Mac"]', NULL, NULL, 0, 1.02, '2026-10-17 04:47:13', '2026-10-17 04:47:13')
