VALUES (22621, 'tt0113280', NULL, 'Heavy', 'Heavy', 'movie', 1995, 'https://image.tmdb.org/t/p/w500/xo2KsY7hOHDqpgYlDStL56zmgaq.jpg', 'https://image.tmdb.org/t/p/original/kqaIZ94OVxAdjsxh2i1GmTFliJd.jpg', 'Victor is a cook who works in a greasy roadside restaurant owned by his mother, Dolly. It''s just the two of them, a waitress named Delores, and a heavy drinking regular, Leo. But things change when Callie, a beautiful college dropout, shows up as a new waitress and steals Victor''s heart. But Victor is too shy to do anything about it, and too self-consciously overweight to dream of winning Callie away.', NULL, NULL, 1.7681, 6.6, 0, 9.51, '2026-10-17 04:47:13', '2026-10-17 04:47:13')
