VALUES (12107, 'tt0144528', NULL, 'Nutty Professor II: The Klumps', 'Nutty Professor II: The Klumps', 'movie', 2000, 'https://image.tmdb.org/t/p/w500/v8gI95Eio7kAjixyqYHxNKmJTmm.jpg', 'https://image.tmdb.org/t/p/original/i3oT0v1KVDZEq8oOZdAAqy78Vub.jpg', 'The hilarity begins when professor Sherman Klump finds romance with fellow DNA specialist, Denise Gaines, and discovers a brilliant formula that reverses aging. But Sherman''s thin and obnoxious alter ego, Buddy Love, wants out...and a big piece of the action. And when Buddy gets loose, things get seriously nutty.', NULL, NULL, 5.4946, 5.0, 0, 7.01, '2026-10-17 04:47:13', '2026-10-17 04:47:13')
