VALUES (27072, 'tt0093593', NULL, 'On the Silver Globe', 'Na Srebrnym Globie', 'movie', 1989, 'https://image.tmdb.org/t/p/w500/4zzam82e6rCY2Ktm0fyRoseHhkh.jpg', 'https://image.tmdb.org/t/p/original/5nZ0ax5n5k9MogcGX3IxVjlCMRt.jpg', 'A small group of cosmic explorers, including a woman, leaves Earth to start a new civilization. They do not realize that within themselves they carry the end of their own dream. They die one by one, while their children revert to a primitive native culture, creating new myths and a new god.', NULL, NULL, 3.0243, 7.683, 0, 33.999, '2026-07-15 12:01:52', '2026-10-17 04:47:13')
