VALUES (264660, 'tt0470752', NULL, 'Ex Machina', 'Ex Machina', 'movie', 2015, 'https://image.tmdb.org/t/p/w500/dmJW8IAKHKxFNiUnoDR7JfsK7Rp.jpg', 'https://image.tmdb.org/t/p/original/uqOuJ50EtTj7kkDIXP8LCg7G45D.jpg', 'Caleb, a coder at the world''s largest internet company, wins a competition to spend a week at a private mountain retreat belonging to Nathan, the reclusive CEO of the company. But when Caleb arrives at the remote location he finds that he will have to participate in a strange and fascinating experiment in which he must interact with the world''s first true artificial intelligence, housed in the body of a beautiful robot girl.', NULL, NULL, 10.4872, 7.571, 0, 54.536, '2026-07-15 12:01:52', '2026-10-17 04:47:13')
