VALUES (790, 'tt0080749', NULL, 'The Fog', 'The Fog', 'movie', 1980, 'https://image.tmdb.org/t/p/w500/12EeSboRofP3CI4SPmMFNNXCbtY.jpg', 'https://image.tmdb.org/t/p/original/pAOLiapALC7Q5pcCPDTA6P9pRuv.jpg', 'Strange things begin to occur as a tiny California coastal town prepares to commemorate its centenary. Inanimate objects spring eerily to life; Rev. Malone stumbles upon a dark secret about the town''s founding; radio announcer Stevie witnesses a mystical fire; and hitchhiker Elizabeth discovers the mutilated corpse of a fisherman. Then a mysterious iridescent fog descends upon the village, and more people start to die.', NULL, NULL, 10.0779, 6.74, 0, 41.52, '2026-07-15 12:01:52', '2026-10-17 04:47:13')
