VALUES (170, 'tt0289043', NULL, '28 Days Later', '28 Days Later', 'movie', 2002, 'https://image.tmdb.org/t/p/w500/sQckQRt17VaWbo39GIu0TMOiszq.jpg', 'https://image.tmdb.org/t/p/original/aJFwk1clMal1prxAvKAgHxKPAf.jpg', 'Twenty-eight days after a killer virus was accidentally unleashed from a British research facility, a small group of London survivors are caught in a desperate struggle to protect themselves from the infected. Carried by animals and humans, the virus turns those it infects into homicidal maniacs -- and it''s absolutely impossible to contain.', NULL, NULL, 13.2636, 7.244, 0, 5.12945833333333354e+01, '2026-07-20 01:02:04', '2026-10-17 04:47:13')
