VALUES (430214, 'tt6335734', NULL, 'Night Is Short, Walk On Girl', '夜は短し歩けよ乙女', 'movie', 2017, 'https://image.tmdb.org/t/p/w500/cDp45WZNqgAli3u4GTnUhsqFn5K.jpg', 'https://image.tmdb.org/t/p/original/iBl3hhtHC7qQX7jGphIAYLpmpPC.jpg', 'As a group of university students go out for a night on the town, a sophomore known only as "The Girl with Black Hair" experiences a series of surreal encounters with the local nightlife – all the while unaware of the romantic longings of "Senpai", a senior student who has been creating increasingly fantastic and contrived reasons to run into her in an effort to win her heart.', NULL, NULL, 2.2668, 7.443, 0, 1.29622222222222216e+01, '2026-07-21 03:32:24', '2026-10-17 04:47:13')
