VALUES (16538, 'tt1155056', NULL, 'I Love You, Man', 'I Love You, Man', 'movie', 2009, 'https://image.tmdb.org/t/p/w500/xr4zAYsvgTzvMMiWu6qCAP9WBer.jpg', 'https://image.tmdb.org/t/p/original/zLXACaQzLLKmzbSBPpgXW6wfGdv.jpg', 'Peter Klaven is a successful real estate agent who, upon getting engaged to the woman of his dreams, Zooey, discovers, to his dismay and chagrin, that he has no male friend close enough to serve as his Best Man. Peter immediately sets out to rectify the situation, embarking on a series of bizarre and awkward "man-dates."', NULL, NULL, 17.053, 6.6, 0, 10.175, '2026-08-07 03:39:39', '2026-10-17 04:47:13')
